     1	package loja.entrega;
     3	import java.math.BigDecimal;
     4	import java.net.URI;
     5	import java.net.URLEncoder;
     6	import java.net.http.HttpClient;
     7	import java.net.http.HttpRequest;
     8	import java.net.http.HttpResponse;
     9	import java.nio.charset.StandardCharsets;
    10	import java.time.Duration;
    11	import java.util.concurrent.CompletableFuture;
    12	import java.util.concurrent.TimeUnit;
    14	import org.springframework.beans.factory.annotation.Value;
    15	import org.springframework.stereotype.Component;
    16	import tools.jackson.databind.ObjectMapper;
    18	import loja.dominio.Dinheiro;
    19	import loja.dominio.NegocioException;
    20	import loja.entrega.ModalidadeEntrega.Cotacao;
    22	@Component
    23	public class TransLogClient implements Transportadora {
    25	    private static final Duration LIMITE = Duration.ofSeconds(2);
    27	    private final String baseUrl;
    28	    private final ObjectMapper mapper;
    29	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(LIMITE).build();
    31	    public TransLogClient(@Value("${translog.url:}") String baseUrl, ObjectMapper mapper) {
    32	        this.baseUrl = baseUrl == null ? "" : baseUrl.trim().replaceAll("/+$", "");
    33	        this.mapper = mapper;
    34	    }
    36	    record Resposta(BigDecimal valor, Integer prazoDias) {
    37	    }
    39	    @Override
    40	    public Cotacao cotar(String cep, BigDecimal pesoKg, String servico) {
    41	        if (baseUrl.isEmpty()) {
    42	            throw foraDoAr();
    43	        }
    44	        CompletableFuture<HttpResponse<String>> futuro = null;
    45	        try {
    46	            URI uri = URI.create(baseUrl + "/cotacao?cep=" + enc(cep) + "&pesoKg=" + enc(pesoKg.toPlainString())
    47	                    + "&servico=" + enc(servico));
    48	            HttpRequest req = HttpRequest.newBuilder(uri).timeout(LIMITE).GET().build();
    49	            futuro = http.sendAsync(req, HttpResponse.BodyHandlers.ofString());
    50	            HttpResponse<String> resp = futuro.get(LIMITE.toMillis(), TimeUnit.MILLISECONDS);
    51	            if (resp.statusCode() == 404) {
    52	                throw NegocioException.invalido("MODALIDADE_INDISPONIVEL");
    53	            }
    54	            if (resp.statusCode() != 200) {
    55	                throw foraDoAr();
    56	            }
    57	            Resposta r = mapper.readValue(resp.body(), Resposta.class);
    58	            if (r == null || r.valor() == null || r.prazoDias() == null
    59	                    || r.valor().signum() < 0 || r.prazoDias() < 0) {
    60	                throw foraDoAr();
    61	            }
    62	            return new Cotacao(Dinheiro.arredondar(r.valor()), r.prazoDias());
    63	        } catch (NegocioException e) {
    64	            throw e;
    65	        } catch (InterruptedException e) {
    66	            Thread.currentThread().interrupt();
    67	            throw foraDoAr();
    68	        } catch (Exception e) {
    69	            if (futuro != null) {
    70	                futuro.cancel(true);
    71	            }
    72	            throw foraDoAr();
    73	        }
    74	    }
    76	    private static String enc(String s) {
    77	        return URLEncoder.encode(s, StandardCharsets.UTF_8);
    78	    }
    80	    private static NegocioException foraDoAr() {
    81	        return new NegocioException("TRANSPORTADORA_INDISPONIVEL", 503);
    82	    }
    83	}
