     1	package loja.pagamento;
     3	import java.math.BigDecimal;
     4	import java.math.MathContext;
     6	import org.springframework.stereotype.Component;
     8	import loja.dominio.Dinheiro;
     9	import loja.dominio.NegocioException;
    11	@Component
    12	public class Cartao implements FormaPagamento {
    14	    private static final int MAX_PARCELAS = 12;
    15	    private static final int MAX_SEM_JUROS = 3;
    16	    private static final BigDecimal TAXA = new BigDecimal("0.0199");
    17	    private static final MathContext MC = MathContext.DECIMAL128;
    19	    @Override
    20	    public String codigo() {
    21	        return "CARTAO";
    22	    }
    24	    @Override
    25	    public void validarParcelas(int parcelas) {
    26	        if (parcelas < 1 || parcelas > MAX_PARCELAS) {
    27	            throw NegocioException.invalido("PARCELAMENTO_INVALIDO");
    28	        }
    29	    }
    31	    @Override
    32	    public Cobranca cobrar(BigDecimal total, int parcelas, boolean comCupom) {
    33	        BigDecimal n = BigDecimal.valueOf(parcelas);
    34	        if (parcelas <= MAX_SEM_JUROS) {
    35	            return new Cobranca(total, Dinheiro.arredondar(total.divide(n, MC)));
    36	        }
    38	        BigDecimal fator = BigDecimal.ONE.add(TAXA).pow(parcelas, MC);
    39	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MC), MC);
    40	        BigDecimal parcela = Dinheiro.arredondar(total.multiply(TAXA).divide(divisor, MC));
    41	        return new Cobranca(Dinheiro.arredondar(parcela.multiply(n)), parcela);
    42	    }
    43	}
