    59	    public Resumo calcular(PedidoRequest req) {
    60	        if (req == null) {
    61	            throw invalido("PEDIDO_INVALIDO");
    62	        }
    64	        validarBasico(req);
    66	        Map<String, Produto> catalogo = produtos.buscarVarios(
    67	                req.itens().stream().map(PedidoRequest.Item::sku).toList());
    68	        for (var item : req.itens()) {
    69	            if (!catalogo.containsKey(item.sku())) {
    70	                throw invalido("PRODUTO_INEXISTENTE");
    71	            }
    72	        }
    73	        for (var item : req.itens()) {
    74	            if (catalogo.get(item.sku()).foraDeLinha()) {
    75	                throw invalido("PRODUTO_FORA_DE_LINHA");
    76	            }
    77	        }
    78	        for (var item : req.itens()) {
    79	            if (catalogo.get(item.sku()).estoque() < item.quantidade()) {
    80	                throw invalido("ESTOQUE_INSUFICIENTE");
    81	            }
    82	        }
    84	        NivelClube nivel = req.nivelClube() == null ? null : niveis.get(req.nivelClube());
    85	        if (nivel == null) {
    86	            throw invalido("NIVEL_CLUBE_INVALIDO");
    87	        }
    88	        Regiao regiao = Regiao.de(req.regiao()).orElseThrow(() -> invalido("REGIAO_INVALIDA"));
    89	        if (req.cep() == null || !CEP.matcher(req.cep()).matches()) {
    90	            throw invalido("CEP_INVALIDO");
    91	        }
    92	        ModalidadeEntrega entrega = req.modalidadeEntrega() == null ? null : entregas.get(req.modalidadeEntrega());
    93	        if (entrega == null) {
    94	            throw invalido("MODALIDADE_INVALIDA");
    95	        }
    97	        List<LinhaItem> linhas = req.itens().stream().map(i -> {
    98	            Produto p = catalogo.get(i.sku());
    99	            return new LinhaItem(p.sku(), p.preco(), p.pesoKg(), i.quantidade());
   100	        }).toList();
   101	        BigDecimal subtotal = Dinheiro.arredondar(
   102	                linhas.stream().map(LinhaItem::total).reduce(BigDecimal.ZERO, BigDecimal::add));
   103	        BigDecimal peso = linhas.stream().map(l -> l.pesoKg().multiply(BigDecimal.valueOf(l.quantidade())))
   104	                .reduce(BigDecimal.ZERO, BigDecimal::add);
   107	        Cotacao cotacao = entrega.cotar(new ContextoEntrega(req.cep(), regiao, peso));
   108	        BigDecimal frete = Dinheiro.arredondar(cotacao.valor());
   109	        if (nivel.isentaFrete() && entrega.aceitaIsencaoDoClube()) {
   110	            frete = Dinheiro.ZERO;
   111	        }
   114	        boolean comCupom = req.cupom() != null && !req.cupom().isBlank();
   115	        BigDecimal desconto = Dinheiro.ZERO;
   116	        if (comCupom) {
   117	            Cupom cupom = cupons.get(req.cupom());
   118	            if (cupom == null) {
   119	                throw invalido("CUPOM_INVALIDO");
   120	            }
   121	            var ctx = new ContextoCupom(linhas, subtotal, frete, entrega.temFrete(),
   122	                    () -> !pedidos.cpfTemPedidoPago(req.cliente().cpf()));
   123	            desconto = Dinheiro.arredondar(
   124	                    cupom.desconto(ctx).orElseThrow(() -> invalido("CUPOM_NAO_APLICAVEL")));
   125	        }
   127	        BigDecimal seguro = regiao.seguro(subtotal);
   128	        BigDecimal total = Dinheiro.arredondar(subtotal.subtract(desconto).add(frete).add(seguro));
   131	        FormaPagamento pagamento = req.formaPagamento() == null ? null : pagamentos.get(req.formaPagamento());
   132	        if (pagamento == null) {
   133	            throw invalido("FORMA_PAGAMENTO_INVALIDA");
   134	        }
   135	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
   136	        pagamento.validarParcelas(parcelas);
   137	        pagamento.validarDisponibilidade(total);
   138	        Cobranca cobranca = pagamento.cobrar(total, parcelas, comCupom);
   140	        return new Resumo(subtotal, desconto, frete, cotacao.prazoDias(), seguro,
   141	                cobranca.totalFinal().subtract(total), cobranca.totalFinal(), parcelas, cobranca.valorParcela(),
   142	                nivel.credito(subtotal), nivel.brinde(subtotal));
   143	    }
   145	    private static void validarBasico(PedidoRequest req) {
   146	        if (req.itens() == null || req.itens().isEmpty()) {
   147	            throw invalido("PEDIDO_INVALIDO");
   148	        }
   149	        Set<String> vistos = new HashSet<>();
   150	        for (var item : req.itens()) {
   151	            if (item == null || item.sku() == null || item.sku().isBlank() || item.quantidade() == null
   152	                    || item.quantidade() <= 0 || !vistos.add(item.sku())) {
   153	                throw invalido("PEDIDO_INVALIDO");
   154	            }
   155	        }
   156	        var c = req.cliente();
   157	        if (c == null || c.cpf() == null || c.cpf().isBlank() || c.email() == null || c.email().isBlank()) {
   158	            throw invalido("PEDIDO_INVALIDO");
   159	        }
   160	    }
   161	}
