    22	    private final JdbcClient jdbc;
    23	    private final ObjectMapper mapper;
    25	    public PedidoRepository(JdbcClient jdbc, ObjectMapper mapper) {
    26	        this.jdbc = jdbc;
    27	        this.mapper = mapper;
    28	    }
    30	    public void inserir(Pedido p) {
    31	        jdbc.sql("INSERT INTO pedido (id, cpf, email, situacao, criado_em, resumo) VALUES (?,?,?,?,?,?)")
    32	                .params(p.id(), p.cpf(), p.email(), p.situacao().name(),
    33	                        LocalDateTime.ofInstant(p.criadoEm(), ZoneOffset.UTC), mapper.writeValueAsString(p.resumo()))
    34	                .update();
    35	        int pos = 0;
    36	        for (ItemPedido i : p.itens()) {
    37	            jdbc.sql("INSERT INTO pedido_item (pedido_id, posicao, sku, quantidade) VALUES (?,?,?,?)")
    38	                    .params(p.id(), pos++, i.sku(), i.quantidade()).update();
    39	        }
    40	    }
    42	    public Optional<Pedido> buscar(String id) {
    43	        return buscar(id, false);
    44	    }
    47	    public Optional<Pedido> buscarParaAtualizar(String id) {
    48	        return buscar(id, true);
    49	    }
    51	    private Optional<Pedido> buscar(String id, boolean travar) {
    52	        String sql = "SELECT * FROM pedido WHERE id = ?" + (travar ? " FOR UPDATE" : "");
    53	        return jdbc.sql(sql).param(id).query((rs, n) -> {
    54	            Instant criado = rs.getObject("criado_em", LocalDateTime.class).toInstant(ZoneOffset.UTC);
    55	            return new Pedido(rs.getString("id"), rs.getString("cpf"), rs.getString("email"),
    56	                    Situacao.valueOf(rs.getString("situacao")), criado,
    57	                    mapper.readValue(rs.getString("resumo"), Resumo.class), List.of(),
    58	                    rs.getString("codigo_rastreio"), rs.getString("id_transacao"));
    59	        }).optional().map(p -> new Pedido(p.id(), p.cpf(), p.email(), p.situacao(), p.criadoEm(), p.resumo(),
    60	                itens(p.id()), p.codigoRastreio(), p.idTransacao()));
    61	    }
    63	    private List<ItemPedido> itens(String id) {
    64	        return jdbc.sql("SELECT sku, quantidade FROM pedido_item WHERE pedido_id = ? ORDER BY posicao").param(id)
    65	                .query((rs, n) -> new ItemPedido(rs.getString(1), rs.getInt(2))).list();
    66	    }
    68	    public void atualizarSituacao(String id, Situacao situacao) {
    69	        jdbc.sql("UPDATE pedido SET situacao = ? WHERE id = ?").params(situacao.name(), id).update();
    70	    }
    72	    public void registrarPagamento(String id, String idTransacao) {
    73	        jdbc.sql("UPDATE pedido SET situacao = ?, id_transacao = ? WHERE id = ?")
    74	                .params(Situacao.PAGO.name(), idTransacao, id).update();
    75	    }
    77	    public void registrarEnvio(String id, String codigoRastreio) {
    78	        jdbc.sql("UPDATE pedido SET situacao = ?, codigo_rastreio = ? WHERE id = ?")
    79	                .params(Situacao.ENVIADO.name(), codigoRastreio, id).update();
    80	    }
    83	    public boolean cpfTemPedidoPago(String cpf) {
    84	        List<String> situacoes = Arrays.stream(Situacao.values()).filter(Situacao::pagoEAtivo).map(Enum::name)
    85	                .toList();
    86	        String marcas = String.join(",", situacoes.stream().map(s -> "?").toList());
    87	        return jdbc.sql("SELECT COUNT(*) FROM pedido WHERE cpf = ? AND situacao IN (" + marcas + ")")
    88	                .params(concat(cpf, situacoes)).query(Long.class).single() > 0;
    89	    }
    91	    private static List<Object> concat(String cpf, List<String> situacoes) {
    92	        List<Object> l = new java.util.ArrayList<>();
    93	        l.add(cpf);
    94	        l.addAll(situacoes);
    95	        return l;
    96	    }
    97	}
