    86	        String marcas = String.join(",", situacoes.stream().map(s -> "?").toList());
    87	        return jdbc.sql("SELECT COUNT(*) FROM pedido WHERE cpf = ? AND situacao IN (" + marcas + ")")
    88	                .params(concat(cpf, situacoes)).query(Long.class).single() > 0;
